const FREE_QUESTION_MIX = {
  "original": 6,
  "easy": 2,
  "medium": 5,
  "hard": 2
};
// END GENERATED QUESTION SETS
const TEST_SIZE = 15;
const TEST_SECONDS = 6 * 60;

const screens = {
  home: document.getElementById("home-screen"),
  quiz: document.getElementById("quiz-screen"),
  result: document.getElementById("result-screen")
};

const quizForm = document.getElementById("quiz-form");
const timerEl = document.getElementById("timer");
const timerCard = document.querySelector(".timer-card");
const topbarTime = document.querySelector(".time-display");
const topbarStatus = document.querySelector(".status-dot");
const progressBar = document.getElementById("progress-bar");
const questionCount = document.getElementById("question-count");
const answeredCount = document.getElementById("answered-count");

let currentQuestions = [];
let selectedAnswers = {};
let secondsLeft = TEST_SECONDS;
let timerId = null;

document.getElementById("start-btn").addEventListener("click", startQuiz);
document.getElementById("submit-btn").addEventListener("click", () => finishQuiz());
document.getElementById("back-btn").addEventListener("click", showHome);
document.getElementById("restart-btn").addEventListener("click", startQuiz);

function showScreen(name) {
  Object.values(screens).forEach((screen) => screen.classList.remove("active"));
  screens[name].classList.add("active");
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function showHome() {
  clearInterval(timerId);
  secondsLeft = TEST_SECONDS;
  updateTimer();
  topbarStatus.textContent = "Practice Mode";
  topbarStatus.classList.remove("complete");
  showScreen("home");
}

function startQuiz() {
  selectedAnswers = {};
  secondsLeft = TEST_SECONDS;
  currentQuestions = buildMixedQuestions(FREE_QUESTION_MIX);
  renderQuiz();
  updateTimer();
  topbarStatus.textContent = "Active Test";
  topbarStatus.classList.remove("complete");
  clearInterval(timerId);
  timerId = setInterval(tick, 1000);
  showScreen("quiz");
}


function buildMixedQuestions(mixConfig) {
  const selected = [
    ...takeRandom(QUESTION_BANK, mixConfig.original),
    ...takeRandom(EASY_QUESTION_BANK, mixConfig.easy),
    ...takeRandom(MEDIUM_QUESTION_BANK, mixConfig.medium),
    ...takeRandom(HARD_QUESTION_BANK, mixConfig.hard),
  ];
  return shuffle(selected).slice(0, TEST_SIZE);
}

function takeRandom(bank, count) {
  return shuffle([...bank]).slice(0, count);
}

function renderQuiz() {
  quizForm.innerHTML = currentQuestions
    .map((item, index) => {
      const options = item.options
        .map((option, optionIndex) => {
          const letter = String.fromCharCode(97 + optionIndex);
          return `
            <label class="option">
              <input type="radio" name="q${index}" value="${optionIndex}" />
              <span>${letter}. ${option}</span>
            </label>
          `;
        })
        .join("");

      return `
        <article class="question-card">
          <div class="question-head">
            <span class="question-index">${index + 1}</span>
            <p class="question-text">${item.q}</p>
          </div>
          <div class="options-grid">${options}</div>
        </article>
      `;
    })
    .join("");

  quizForm.querySelectorAll("input[type='radio']").forEach((input) => {
    input.addEventListener("change", (event) => {
      const index = Number(event.target.name.replace("q", ""));
      selectedAnswers[index] = Number(event.target.value);
      updateProgress();
    });
  });

  updateProgress();
}

function tick() {
  secondsLeft -= 1;
  updateTimer();
  if (secondsLeft <= 0) {
    finishQuiz(true);
  }
}

function updateTimer() {
  const minutes = Math.floor(secondsLeft / 60).toString().padStart(2, "0");
  const seconds = (secondsLeft % 60).toString().padStart(2, "0");
  timerEl.textContent = `${minutes}:${seconds}`;
  topbarTime.textContent = `${minutes}:${seconds}`;
  timerCard.classList.toggle("warning", secondsLeft <= 60);
}

function updateProgress() {
  const answered = Object.keys(selectedAnswers).length;
  questionCount.textContent = `Question ${Math.min(answered + 1, TEST_SIZE)} of ${TEST_SIZE}`;
  answeredCount.textContent = `${answered} answered`;
  progressBar.style.width = `${(answered / TEST_SIZE) * 100}%`;
}

function finishQuiz() {
  clearInterval(timerId);
  topbarStatus.textContent = "Completed";
  topbarStatus.classList.add("complete");
  const score = currentQuestions.reduce((total, item, index) => {
    return total + (selectedAnswers[index] === item.answer ? 1 : 0);
  }, 0);
  renderResult(score);
  showScreen("result");
}

function renderResult(score) {
  const percent = Math.round((score / TEST_SIZE) * 100);
  const band = getBand(percent);

  document.getElementById("result-title").textContent = band.title;
  document.getElementById("result-icon").textContent = band.icon;
  document.getElementById("score-percent").textContent = `${percent}%`;
  document.getElementById("score-detail").textContent = `${score} / ${TEST_SIZE} correct`;

  document.getElementById("review-list").innerHTML = currentQuestions
    .map((item, index) => {
      const selected = selectedAnswers[index];
      const isCorrect = selected === item.answer;
      const userAnswer = selected === undefined ? "No answer" : `${letter(selected)}. ${item.options[selected]}`;
      const correctAnswer = `${letter(item.answer)}. ${item.options[item.answer]}`;
      return `
        <article class="review-card ${isCorrect ? "correct" : "wrong"}">
          <h4>${index + 1}. ${item.q}</h4>
          <p class="${isCorrect ? "answer-good" : "answer-bad"}">Your answer: ${userAnswer}</p>
          <p><strong>Correct answer:</strong> ${correctAnswer}</p>
        </article>
      `;
    })
    .join("");
}

function getBand(percent) {
  if (percent >= 80) return { title: "Excellent", icon: "★★★★★" };
  if (percent >= 70) return { title: "Very Good", icon: "👍" };
  if (percent >= 50) return { title: "Need More Practice", icon: "Keep practicing" };
  return { title: "Study More", icon: "Review the basics" };
}

function letter(index) {
  return String.fromCharCode(97 + index);
}

function shuffle(items) {
  for (let i = items.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [items[i], items[j]] = [items[j], items[i]];
  }
  return items;
}
